[MITM]
hostname = patient-api.suh.cn, userpms-api.suh.cn

[Rewrite]
request if ${url} ~= /^https:\/\/userpms-api\.suh\.cn\/apt\/api\/bannar\/PageList\?sysSearchKey=sysPat&showSearchKey=advertising&pageIndex=1&pagesize=100&lanSearchValue=1&locationSearchKey=&status=1&/i then reject_dict(200)
request if ${url} ~= /^https:\/\/patient-api\.suh\.cn\/apt\/api\/userinfo\/GetNotice\?appname=pmsys&channel=6&device=ios&language=1&source=2&version=/i then reject_dict(200)
